contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 _value) public payable {
        uint256 preTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 preBurnerBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(_value <= preBurnerBalance);

        c.burn(_value); if (__ESBMC_reverted()) return;

        uint256 postTotalDistributed;
        postTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(postTotalDistributed == preTotalDistributed - _value);
    }
}

