pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 _value) internal {
        uint256 preTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { preTotalDistributed = __r; } catch { return; }
        uint256 preBurnerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { preBurnerBalance = __r; } catch { return; }
        vm.assume(_value <= preBurnerBalance);
        try c.burn(_value) {} catch { return; }
        uint256 postTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { postTotalDistributed = __r; } catch { return; }
        assertTrue(postTotalDistributed == preTotalDistributed - _value);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
